136: function initStars() {
137:   const canvas = $('#starfield');
138:   const ctx = canvas.getContext('2d');
139:   const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
140:   let w = 0, h = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);
141:   let stars = [], shooting = null, last = performance.now();
142:   function resize() {
143:     w = window.innerWidth; h = window.innerHeight;
144:     canvas.width = w * dpr; canvas.height = h * dpr;
145:     canvas.style.width = w + 'px'; canvas.style.height = h + 'px';
146:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
147:     const count = Math.min(220, Math.round((w * h) / 9000));
148:     stars = Array.from({ length: count }, () => ({
149:       x: Math.random() * w, y: Math.random() * h,
150:       r: Math.random() * 1.2 + 0.25,
151:       a: Math.random() * 0.55 + 0.18,
152:       sp: Math.random() * 0.014 + 0.003,
153:       ph: Math.random() * Math.PI * 2,
154:       hue: Math.random() < 0.16 ? '#e8c987' : Math.random() < 0.4 ? '#c7d6ff' : '#ffffff',
155:     }));
156:   }
157:   function draw(t) {
158:     ctx.clearRect(0, 0, w, h);
159:     const dt = reduced ? 0 : Math.min(48, t - last); last = t;
160:     for (const s of stars) {
161:       s.ph += s.sp * (dt / 16.7);
162:       const alpha = s.a * (0.6 + 0.4 * Math.sin(s.ph));
163:       ctx.globalAlpha = alpha;
164:       ctx.fillStyle = s.hue;
165:       ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill();
166:       if (s.r > 1.05) {
167:         ctx.globalAlpha = alpha * 0.35;
168:         ctx.fillRect(s.x - 3, s.y - 0.3, 6, 0.6);
169:         ctx.fillRect(s.x - 0.3, s.y - 3, 0.6, 6);
170:       }
171:     }
172:     if (!reduced) {
173:       if (!shooting && Math.random() < 0.0025) {
174:         shooting = { x: Math.random() * w * 0.7 + w * 0.15, y: Math.random() * h * 0.35, vx: 2.6 + Math.random() * 2, vy: 1.4 + Math.random(), life: 1 };
175:       }
176:       if (shooting) {
177:         shooting.x += shooting.vx * 4; shooting.y += shooting.vy * 4; shooting.life -= 0.012;
178:         ctx.globalAlpha = Math.max(0, shooting.life) * 0.8;
179:         ctx.strokeStyle = '#f5e7c2'; ctx.lineWidth = 1.2;
180:         ctx.beginPath(); ctx.moveTo(shooting.x, shooting.y); ctx.lineTo(shooting.x - 70, shooting.y - 36); ctx.stroke();
181:         if (shooting.life <= 0) shooting = null;
182:       }
183:     }
184:     ctx.globalAlpha = 1;
185:     if (!reduced) requestAnimationFrame(draw);
186:   }
187:   resize();
188:   window.addEventListener('resize', resize);
189:   if (reduced) draw(0); else requestAnimationFrame(draw);
190: }
