759:     if (effects[k]) out.push(tagHtml(`${effects[k] > 0 ? '+' : ''}${effects[k]} ${t(label)}`, effects[k] > 0));
760:   }
761:   if (effects.followersPct) out.push(tagHtml(t('{n}% Souls', { n: (effects.followersPct > 0 ? '+' : '') + Math.round(effects.followersPct * 100) }), effects.followersPct > 0));
762:   if (effects.relic) out.push(tagHtml(t('+ Relic'), true));
763:   return out.join('');
