772:     <div class="choice-list">${ev.choices.map((c, i) => {
773:       const ok = affordableEffects(c.effects);
774:       return `<button class="choice" data-choice="${i}" ${ok ? '' : 'disabled'}>
775:         <span class="ch-label">${esc(c.label)}</span>
776:         <span class="ch-tags">${effectTags(c.effects)}</span>
777:       </button>`;
778:     }).join('')}</div>`);
779:   $$('#modalRoot .choice').forEach(btn => btn.addEventListener('click', () => {
780:     if (btn.disabled) return;
