600: function renderBoard(stand, might) {
601:   const entries = [
602:     ...state.rivals.map(r => ({ name: r.name, epithet: r.epithet, pantheon: r.pantheon, domain: r.domain, might: r.might, player: false })),
603:     { name: 'YOU', might, domain: state.god.domain, pantheon: state.god.pantheon, epithet: state.god.epithet, player: true },
604:   ].sort((a, b) => b.might - a.might);
605:   const playerIndex = entries.findIndex(e => e.player);
606:   const rows = entries.map((e, i) => {
607:     const playerRank = i + 1;
608:     if (!e.player && i >= 20) return '';
609:     const dd = domainOf(e.domain);
610:     const prev = state.lastRanks ? state.lastRanks[e.player ? 'YOU' : e.name] : null;
611:     let trend = '';
612:     if (prev) {
613:       const diff = prev - playerRank;
614:       if (diff > 0) trend = `<span class="t-trend up">▲ ${diff}</span>`;
615:       else if (diff < 0) trend = `<span class="t-trend down">▼ ${Math.abs(diff)}</span>`;
616:       else trend = `<span class="t-trend">—</span>`;
617:     }
618:     const prow = e.player;
619:     return `<li class="throne${prow ? ' you' : ''}${playerRank <= 3 ? ' top' : ''}" ${prow ? '' : `data-rival="${state.rivals.findIndex(r => r.name === e.name)}"`}>
620:       <span class="t-rank">${playerRank}</span>
621:       <span class="t-sigil" style="color:${dd.color}">${icon(DOMAIN_ICONS[dd.id])}</span>
622:       <span class="t-info"><span class="t-name">${esc(prow ? state.god.name : e.name)}${prow ? `<span class="you-tag">${esc(t('YOU'))}</span>` : ''}</span><span class="t-sub">${esc(domainName(dd))} · ${esc(t(e.pantheon))}</span></span>
623:       <span class="t-might">${fmt(e.might)}${trend}</span>
624:     </li>`;
625:   }).join('');
626:   $('#leaderboard').innerHTML = rows;
627:   $('#boardCrown').innerHTML = icon('crown');
628:   $('#playerStanding').innerHTML = `<span class="standing-text">${esc(t('Your standing'))}</span><span class="standing-badge">#${stand.rank} <span style="color:var(--muted-2);font-size:9px">${esc(t('of {n}', { n: stand.total }))}</span></span>`;
629:   if (playerIndex >= 20) {
630:     const note = document.createElement('div');
631:     note.className = 'standing-text';
632:     note.style.padding = '6px 4px 0';
633:     note.innerHTML = t('You are outside the Twenty Thrones. <b>{n}</b> might.', { n: fmt(might) });
634:     $('#playerStanding').prepend(note);
635:   }
636: }
