200: function tone(freq, dur = 0.14, type = 'sine', vol = 0.035, delay = 0) {
201:   if (!soundOn) return;
202:   const ctx = audio(); if (!ctx) return;
203:   const t0 = ctx.currentTime + delay;
204:   const osc = ctx.createOscillator();
205:   const g = ctx.createGain();
206:   osc.type = type; osc.frequency.setValueAtTime(freq, t0);
207:   g.gain.setValueAtTime(0, t0);
208:   g.gain.linearRampToValueAtTime(vol, t0 + 0.015);
209:   g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
210:   osc.connect(g); g.connect(ctx.destination);
211:   osc.start(t0); osc.stop(t0 + dur + 0.02);
212: }
