function missingReasonText(action) {
  if ((state.ap || 0) < action.ap) return t('Requires {n} actions', { n: action.ap });
  for (const [k, v] of Object.entries(action.cost || {})) {
    if ((k === 'faith' || k === 'power') && state.stats[k] < v) return t('Requires {n} ' + k, { n: v });
